import{_ as a,o as t,c as r,a0 as i}from"./chunks/framework.B7o6dWmz.js";const u=JSON.parse('{"title":"Pricing and margin","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pricing.md","filePath":"guide/pricing.md","lastUpdated":1793979958000}'),o={name:"guide/pricing.md"};function n(s,e,c,l,h,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="pricing-and-margin" tabindex="-1">Pricing and margin <a class="header-anchor" href="#pricing-and-margin" aria-label="Permalink to &quot;Pricing and margin&quot;">​</a></h1><p>NetonAPI prices have a single anchor: <strong>the official price</strong>. Every price is written as &quot;a share of the official price&quot;, so customers can compare easily and operators can do the math.</p><h2 id="where-a-user-s-price-comes-from" tabindex="-1">Where a user&#39;s price comes from <a class="header-anchor" href="#where-a-user-s-price-comes-from" aria-label="Permalink to &quot;Where a user&#39;s price comes from&quot;">​</a></h2><p>When a user calls a model, the price is looked up in this order and the first match wins:</p><table tabindex="0"><thead><tr><th>Layer</th><th>When it applies</th><th>How it is written</th></tr></thead><tbody><tr><td>Negotiated price</td><td>The operator negotiated this model for <strong>this user</strong></td><td>N% of official, e.g. 85%</td></tr><tr><td>Group price</td><td>The user&#39;s API key belongs to a billing group (enterprise, dedicated line…)</td><td>A group ratio, or per-model prices inside the group</td></tr><tr><td>Site price</td><td>None of the above</td><td>Official × site markup (a model can have its own markup)</td></tr></tbody></table><p>In the console, users see each model&#39;s price, what share of the official price it is, and whether it is a negotiated price. In the admin console, the Negotiated Pricing page shows which layer each of that user&#39;s prices comes from.</p><h2 id="an-example" tabindex="-1">An example <a class="header-anchor" href="#an-example" aria-label="Permalink to &quot;An example&quot;">​</a></h2><p>Say Claude Sonnet&#39;s official price is $3 input / $15 output per million tokens and the site markup is 1.0 (selling at official price):</p><ul><li>A regular user pays $3 / $15.</li><li>The enterprise group has ratio 0.95: $2.85 / $14.25.</li><li>Key account Acme negotiated 85%: $2.55 / $12.75.</li></ul><p>One Acme request with 10,000 input and 2,000 output tokens is charged <code>10,000 × 2.55 / 1,000,000 + 2,000 × 12.75 / 1,000,000 = $0.051</code> — exactly what the unit prices in their console add up to.</p><h2 id="why-you-can-t-sell-at-a-loss" tabindex="-1">Why you can&#39;t sell at a loss <a class="header-anchor" href="#why-you-can-t-sell-at-a-loss" aria-label="Permalink to &quot;Why you can&#39;t sell at a loss&quot;">​</a></h2><p>Every upstream channel records its own cost, e.g. &quot;OpenAI direct at 82% of official&quot; or &quot;partner relay at 55%&quot;. Before any price is saved — site, group or negotiated — NetonAPI checks the margin on <strong>every channel that would actually serve it</strong>:</p><ul><li>Below cost: the price can&#39;t be saved, and you are told which group, channel and price component loses money.</li><li>Below your minimum margin: also refused.</li></ul><p>In the example above, if the channel carrying Claude costs 90% of official, the 85% negotiated price can&#39;t be saved — use a cheaper channel or give a smaller discount.</p><p>The model pricing list shows each model&#39;s <strong>worst margin</strong> across all group × channel combinations, with losses in red; the overview breaks down revenue, cost and margin by group and channel.</p><h2 id="when-the-official-price-changes" tabindex="-1">When the official price changes <a class="header-anchor" href="#when-the-official-price-changes" aria-label="Permalink to &quot;When the official price changes&quot;">​</a></h2><p>NetonAPI periodically pulls official prices from a public source (the same one new-api uses by default; models.dev, LiteLLM or OpenRouter also work), lists every increase and decrease, and applies them after an operator confirms. Because every price is a share of the official price, site, group and negotiated prices all follow automatically — the &quot;85%&quot; you promised a customer stays true.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li><strong>Cache</strong>: cache reads and writes are priced separately; when an upstream has no cache price, cached tokens are billed at the input price, never given away.</li><li><strong>Per call and long context</strong>: image models can be priced per call; long-context models can be tiered by input length.</li><li><strong>Ledger</strong>: each request reserves an upper bound first and settles on actual usage, with the price snapshot frozen per request — price changes never affect in-flight requests.</li><li><strong>Price history</strong>: every change records who, when, and from what to what.</li></ul>',19)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
